"use client";
import { useRef } from "react";
import {
  TypeGlyphs,
  typeInteractive,
  typeUnits,
  useTypeMotion,
  type TypographyMotionProps,
} from "./typography-shared";
import { typeStaggerProgress } from "./typography-math";
export interface CharacterAppearProps extends TypographyMotionProps {
  order?: "sequential" | "random";
  stagger?: number;
  dimOpacity?: number;
}
/** Opacity-only glyph reveal; random order is stable across server/client renders. */
export function CharacterAppear({
  text = "Every detail makes a difference.",
  order = "sequential",
  stagger = 0.65,
  dimOpacity = 0,
  ...props
}: CharacterAppearProps) {
  const root = useRef<HTMLSpanElement>(null);
  useTypeMotion(
    root,
    props,
    (p) => {
      const units = typeUnits(root.current!);
      const orderMap = units
        .map((_, i) => i)
        .sort((a, b) => Math.sin(a * 127.1 + 1) - Math.sin(b * 127.1 + 1));
      units.forEach((unit, i) => {
        const rank = order === "random" ? orderMap.indexOf(i) : i;
        unit.style.opacity = String(
          dimOpacity + (1 - dimOpacity) * typeStaggerProgress(p, rank, units.length, stagger),
        );
      });
    },
    `${text}:${order}:${stagger}:${dimOpacity}`,
  );
  return (
    <span
      ref={root}
      className={props.className}
      style={{ display: "inline-block", ...props.style }}
      aria-label={text}
      data-typography="character-appear"
      {...typeInteractive(props.trigger)}
    >
      <span aria-hidden="true">
        <TypeGlyphs text={text} />
      </span>
    </span>
  );
}
